extern "C" { struct PhysicsState{double x,z,heading,speed,vx,vz;}; static PhysicsState s{}; __attribute__((used)) void physics_reset(){s={0,105,3.1415926535/2,0,0,0};} __attribute__((used)) PhysicsState* physics_state(){return &s;} __attribute__((used)) int physics_step(double dt,double throttle,double brake,double steer,int assist){double max=assist==2?92:(assist==1?86:80);double drag=.0029*s.speed*s.speed+.52;s.speed=std::clamp(s.speed+(18*throttle-31*brake-drag)*dt,-4.0,max);double r=std::min(1.0,std::abs(s.speed)/50.0),boost=1.25-r*.45;s.heading+=std::clamp(steer,-1.0,1.0)*boost*s.speed*.018*dt;double grip=assist==0?.94:(assist==1?.88:.79);double tx=std::sin(s.heading)*s.speed,tz=std::cos(s.heading)*s.speed,k=1-std::pow(1-grip,dt*60);s.vx+=(tx-s.vx)*k;s.vz+=(tz-s.vz)*k;s.x+=s.vx*dt;s.z+=s.vz*dt;double nx=s.x/75,nz=s.z/150,d=std::hypot(nx,nz);if(d>1||d<.67){double target=d>1?.985:.685;s.x=nx/d*target*75;s.z=nz/d*target*150;s.vx*=-.24;s.vz*=-.24;s.speed*=.46;return 1;}return 0;} }
